# coding: utf-8
"""020: traceable, authored project graph; no LLM or calibrated similarity model."""
import html,json,hashlib
from pathlib import Path
from dossier_governance import digest
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'04-知识库/标杆案例/2025-00-嫦娥钻取采样'
read=lambda p:json.loads(p.read_text())
def save(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def build(p=P):
 demo=read(p/'割胶机器人-迁移试读.json');revision=demo['source_archive']['revision'];folder=p/'版本'/revision
 snap=read(folder/'snapshot.json');entry=next(x for x in read(p/'版本/版本索引.json')['versions']if x['version']==revision)
 assert digest(snap)==entry['snapshot_sha256'];assert digest(read(folder/'manifest.json'))==entry['manifest_sha256']
 d=snap['evidence'];K={x['id']:x for x in d['knowledge']};C={x['id']:x for x in d['claims']};S={x['id']:x for x in d['sources']};RS={x['id']:x for x in demo['sources']};RC={x['id']:x for x in demo['external_claims']};M={x['id']:x for x in demo['methods']}
 assert len(RS)==len(demo['sources'])and len(RC)==len(demo['external_claims'])
 for x in RC.values():assert x['source_id']in RS and x['nature']in ['source_summary','platform_inference']
 nodes=[dict(id='SOURCE',type='archived_project',label=d['title'],revision=revision),dict(id='TARGET',type='hypothetical_target',label=demo['target']['name'])];edges=[]
 for k in K.values():nodes.append(dict(id=k['id'],type='platform_mechanism',label=k['title'],source_ids=k['source_ids']))
 for c in C.values():nodes.append(dict(id=c['id'],type='source_statement',label=c['value']))
 for s in S.values():nodes.append(dict(id=s['id'],type='archive_source',label=s['title'],url=s['url']))
 for method in M.values():nodes.append(dict(id=method['id'],type='suggested_method',label=method['title']))
 for x in RC.values():nodes.append(dict(id=x['id'],type=x['nature'],label=x['value']));edges.append(dict(source=x['id'],target=x['source_id'],relation='inferred_from'if x['nature']=='platform_inference'else 'reported_in'))
 for s in RS.values():nodes.append(dict(id=s['id'],type='target_domain_source',label=s['title'],url=s['url'],reading_scope=s['read_scope']))
 for c in C.values():
  edges.append(dict(source='SOURCE',target=c['id'],relation='has_archived_statement'))
  for sid in c['source_ids']:edges.append(dict(source=c['id'],target=sid,relation='reported_in'))
 for k in K.values():
  edges.append(dict(source='SOURCE',target=k['id'],relation='has_archived_interpretation'))
  for cid in k['claim_ids']:
   edges.append(dict(source=k['id'],target=cid,relation='interpreted_from'))
   for sid in C[cid]['source_ids']:edges.append(dict(source=cid,target=sid,relation='reported_in'))
 for study in d['validations']:
  nodes.append(dict(id=study['id'],type='reported_validation',label=study['title'],material=study['material'],limitations=study['limitations']))
  for cid in study['claim_ids']:edges.append(dict(source=study['id'],target=cid,relation='has_reported_result'))
 for profile in snap['research_evidence']['profiles']:
  nodes.append(dict(profile,type='published_test_context',label=profile['title']))
  for kid in profile['knowledge_ids']:edges.append(dict(source=kid,target=profile['id'],relation='has_research_context'))
  edges.append(dict(source=profile['id'],target=profile['validation_id'],relation='describes_test_conditions'))
 for path in demo['paths']:
  assert path['knowledge_id']in K and set(path['claim_ids'])<=C.keys()
  assert set(path['external_claim_ids'])<=RC.keys()and set(path['method_ids'])<=M.keys()
  assert path['status']in ['transfer_hypothesis','excluded_direct_transfer']
  tid=path['id']+'-need';pid=path['id']+'-proposal';vid=path['id']+'-test'
  nodes.extend([dict(id=tid,type='hypothetical_need',label=path['target_problem']),dict(id=pid,type='proposed_solution',label=path['proposal']),dict(id=vid,type='proposed_validation',label=path['experiment'])])
  edges.extend([dict(source='TARGET',target=tid,relation='has_hypothetical_need'),dict(source=path['knowledge_id'],target=tid,relation='excluded_direct_transfer'if path['status']=='excluded_direct_transfer'else 'analogy_hypothesis',verified_transfer=False),dict(source=tid,target=pid,relation='suggested_response'),dict(source=pid,target=vid,relation='requires_validation')])
  for cid in path['claim_ids']:edges.append(dict(source=cid,target=pid,relation='context_for_proposal'))
  for mid in path['method_ids']:edges.append(dict(source=mid,target=pid,relation='guides_proposal'))
  for cid in path['external_claim_ids']:edges.append(dict(source=cid,target=pid,relation='informs_or_limits_proposal'))
 unique={json.dumps(x,sort_keys=True):x for x in edges};edges=list(unique.values());ids={x['id']for x in nodes};assert len(ids)==len(nodes)
 assert all(x['source']in ids and x['target']in ids for x in edges)
 graph=dict(version=demo['version'],nature=demo['kind'],archive_revision=revision,archive_sha256=digest(snap),target=demo['target'],nodes=nodes,edges=edges,paths=demo['paths'],relation_dimensions=demo['relation_dimensions'],limits=demo['limits'])
 save(p/'项目图谱.json',graph)
 selected_knowledge=[K[x['knowledge_id']]for x in demo['paths']]
 claim_ids=list(dict.fromkeys([cid for k in selected_knowledge for cid in k['claim_ids']]+[cid for x in demo['paths']for cid in x['claim_ids']]))
 source_ids=list(dict.fromkeys([sid for k in selected_knowledge for sid in k['source_ids']]+[sid for cid in claim_ids for sid in C[cid]['source_ids']]))
 context=dict(version=demo['version'],kind='authored_transfer_context_not_ai_result',archive_revision=revision,archive_sha256=digest(snap),ordered_context=[dict(priority=1,kind='target_assumptions_and_unknowns',data=demo['target']),dict(priority=2,kind='analogy_hypotheses_and_exclusion',data=demo['paths']),dict(priority=3,kind='archived_mechanisms_claims_and_boundaries',data=dict(knowledge=selected_knowledge,claims=[C[cid]for cid in claim_ids],citations=[S[sid]for sid in source_ids],test_contexts=[x for x in snap['research_evidence']['profiles']if set(x['knowledge_ids'])&{k['id']for k in selected_knowledge}],validations=[x for x in d['validations']if set(x['claim_ids'])&set(claim_ids)])),dict(priority=4,kind='target_domain_facts_and_method_proposals',data=dict(claims=demo['external_claims'],sources=demo['sources'],methods=demo['methods']))],limits=demo['limits'])
 save(p/'图谱调用样例.json',context)
 e=lambda x:html.escape(str(x))
 def dl(items):return '<dl>'+''.join(f'<div><dt>{e(a)}</dt><dd>{e(b)}</dd></div>'for a,b in items)+'</dl>'
 panels={}
 for path in demo['paths']:
  k=K[path['knowledge_id']]
  methodcards=''.join('<article><span>方法</span><h4>'+e(M[mid]['title'])+'</h4><p>'+e(M[mid]['role'])+'</p><p class="muted">输出：'+e(M[mid]['output'])+'</p></article>'for mid in path['method_ids'])
  evidence=''.join(f'<li><b>嫦娥档案</b><p>{e(C[cid]["value"])}</p><small>{e(C[cid]["locator"])} · 冻结内容{revision}</small><a href="档案.html?v=5.1.0#record-{cid}">查看当前档案出处 ↗</a></li>'for cid in path['claim_ids'])
  evidence+=''.join(f'<li><b>{"平台推论"if RC[cid]["nature"]=="platform_inference"else "割胶研究"}</b><p>{e(RC[cid]["value"])}</p><small>{e(RC[cid]["locator"])} · {e(RS[RC[cid]["source_id"]]["read_scope"])}</small><a href="{e(RS[RC[cid]["source_id"]]["url"])}" target="_blank" rel="noopener">原始资料 ↗</a></li>'for cid in path['external_claim_ids'])
  panels[path['id']]=f'<div class="panel-title"><span>{e(path["priority"])}</span><h2>{e(path["title"])}</h2><p>{e(path["relation"])}</p></div>'+dl([('为什么有关联',path['why']),('差异与边界',path['difference'])])+f'<div class="proposal-grid"><article><span>迁移假设</span><h3>在割胶任务里怎样用</h3><p>{e(path["proposal"])}</p></article><article><span>验证计划</span><h3>怎样证明有效</h3><p>{e(path["experiment"])}</p></article></div><div class="method-grid">{methodcards}</div><details><summary>先问清哪些条件</summary><ul>'+''.join('<li>'+e(q)+'</li>'for q in path['questions'])+'</ul></details><details><summary>哪些内容不能照搬</summary><ul>'+''.join('<li>'+e(q)+'</li>'for q in path['cannot_copy'])+'</ul></details><details><summary>查看这条路径的证据与边界</summary><p class="muted">以下来源支持原项目或相关割胶研究；没有一项证明本迁移方案已有效。当前档案链接仅为阅读入口，图谱与调用样例使用冻结0.4.0。</p><ul class="evidence">'+evidence+'</ul></details>'
 def svg_node(x,y,w,h,title,sub,path=None,kind='mechanism'):
  attr=f' role="button" tabindex="0" aria-label="选择{e(title)}" data-select-path="{path}"'if path else ''
  lines=[title[i:i+12]for i in range(0,len(title),12)]
  return f'<g class="node {kind}" transform="translate({x},{y})"{attr}><rect width="{w}" height="{h}" rx="6"/>'+''.join(f'<text x="16" y="{27+i*20}">{e(t)}</text>'for i,t in enumerate(lines))+f'<text class="node-sub" x="16" y="{h-13}">{e(sub)}</text></g>'
 svg=['<svg viewBox="0 0 1100 510" aria-label="嫦娥设计经验与割胶需求的关系图"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7" fill="#8a9b7b"/></marker></defs>']
 labels={'P01':'根据载荷调整运动','P02':'多工况能力取舍','P03':'分层覆盖验证','P04':'保留样品层序'}
 for i,path in enumerate(demo['paths']):
  y=35+i*120;mid=y+38;pid=path['id'];excluded=path['status']=='excluded_direct_transfer'
  svg.append(f'<g class="route-edge" data-edge-path="{pid}"><path class="contains" d="M210,244 C235,244 235,{mid} 260,{mid}"/><path class="contains" d="M880,244 C855,244 855,{mid} 830,{mid}"/><path class="bridge {"excluded"if excluded else ""}" d="M470,{mid} L620,{mid}"/><text class="edge-label" x="545" y="{mid-12}" text-anchor="middle">{"本次排除"if excluded else "迁移待验证"}</text></g>')
  svg.append(svg_node(260,y,210,76,labels[pid],'来源：设计经验',pid));svg.append(svg_node(620,y,210,76,path['target_short'],'目标：待解决问题',pid,'need'))
 svg += [svg_node(20,196,190,96,'嫦娥钻取采样','来源档案 · 0.4.0',kind='project'),svg_node(880,196,190,96,'割胶机器人','假设任务',kind='project'),'</svg>']
 tabs=''.join(f'<button data-select-path="{x["id"]}" aria-pressed="false">{i+1:02d} {e(x["short"])}</button>'for i,x in enumerate(demo['paths']))
 relation=''.join(f'<tr><th>{e(x["dimension"])}</th><td>{e(x["judgement"])}</td><td>{e(x["reason"])}</td></tr>'for x in demo['relation_dimensions'])
 source_list=''.join(f'<li><a href="{e(s["url"])}" target="_blank" rel="noopener">{e(s["title"])}</a><p>{e(s["summary"])}</p><small>{"仅摘要"if s["read_scope"]=="abstract_only"else "相关正文段落核读"} · {e(s["limits"])}</small></li>'for s in demo['sources'])
 blob=json.dumps(dict(panels=panels,paths=demo['paths']),ensure_ascii=False).replace('<','\\u003c')
 page=HTML.replace('@@TABS@@',tabs).replace('@@SVG@@',''.join(svg)).replace('@@RELATION@@',relation).replace('@@SOURCES@@',source_list).replace('@@DATA@@',blob)
 (p/'项目图谱.html').write_text(page)
 report=dict(spec='020',result='pass_graph_structure_only',version=demo['version'],archive_revision=revision,nodes=len(nodes),edges=len(edges),candidate_paths=sum(x['status']=='transfer_hypothesis'for x in demo['paths']),excluded_paths=sum(x['status']=='excluded_direct_transfer'for x in demo['paths']),target_sources=len(RS),target_validation_complete=False,calibrated_similarity_score=None,archive_quality_unchanged=snap['quality']['score'])
 save(p/'图谱验收.json',report);return report
HTML='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>项目图谱｜嫦娥与割胶机器人</title><link rel="icon" href="data:,"><style>
:root{--paper:#f7f5ef;--ink:#252a23;--muted:#6d7468;--line:#dadfd3;--green:#526647;--pale:#edf0e7;--gold:#a78145}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.9 -apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif}header,main,footer{max-width:1240px;margin:auto;padding:22px 30px}header{border-bottom:1px solid var(--line);display:flex;justify-content:space-between;font-size:13px}a{color:var(--green);text-underline-offset:4px}button,select{font:inherit;color:inherit}button{cursor:pointer}h1,h2{font-family:'Songti SC',STSong,serif;font-weight:500}h1{font-size:42px;line-height:1.5;margin:13px 0}h2{font-size:28px;margin:0}h3{font-size:17px;margin:8px 0}h4{font-size:15px;margin:5px 0}p{margin:10px 0}.eyebrow{font-size:12px;color:var(--gold)}.hero{padding:25px 0}.hero>p{font-size:17px;max-width:900px}.muted,small{color:var(--muted);font-size:12px}.project-brief{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:30px 0}.project-brief>div{padding:22px;background:var(--pale);border-left:2px solid #b4c2a9}.project-brief span,.proposal-grid span,.method-grid span{font-size:11px;color:var(--gold)}.project-brief h3{font:500 23px 'Songti SC',serif}.project-brief p{font-size:13px}.takeaway{padding:22px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:18px}.graph-head{display:flex;justify-content:space-between;align-items:baseline;gap:20px;margin:35px 0 14px}.graph-head p{font-size:12px;color:var(--muted)}.graph-wrap{overflow-x:auto;background:#fafaf6;border:1px solid var(--line);border-radius:5px}.graph-wrap svg{width:100%;min-width:880px;display:block}.node rect{fill:#edf0e7;stroke:#b5c3aa}.node.need rect{fill:#f3ece1;stroke:#d1bb98}.node.project rect{fill:#526647;stroke:#526647}.node text{font-size:15px;fill:#252a23;font-family:'PingFang SC',sans-serif}.node .node-sub{font-size:11px;fill:#6d7468}.node.project text{fill:white}.node.project .node-sub{fill:#dce4d6}.node[role=button]{cursor:pointer}.node.selected rect{stroke:#a78145;stroke-width:3}.node.faded,.route-edge.faded{opacity:.35}.contains{fill:none;stroke:#c4cebc;stroke-width:1.5}.bridge{stroke:#a78145;stroke-width:2;stroke-dasharray:6 5;marker-end:url(#arrow)}.bridge.excluded{stroke:#b17868}.edge-label{font:11px 'PingFang SC',sans-serif;fill:#8c7349}.path-tabs{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0 30px}.path-tabs button{border:1px solid var(--line);border-radius:4px;background:transparent;padding:10px 16px;font-size:13px}.path-tabs button[aria-pressed=true]{background:var(--green);color:white;border-color:var(--green)}.panel-title{padding-bottom:20px;border-bottom:1px solid var(--line)}.panel-title>span{font-size:12px;color:var(--gold)}.panel-title>p{color:var(--muted);font-size:14px}dl{margin:10px 0 25px}dl>div{display:grid;grid-template-columns:125px 1fr;gap:24px;padding:17px 0;border-bottom:1px solid var(--line)}dt{font-size:13px;color:var(--muted)}dd{margin:0;font-size:14px}.proposal-grid,.method-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:20px 0}.proposal-grid article{padding:24px;background:var(--pale);border:1px solid var(--line)}.proposal-grid p,.method-grid p{font-size:14px}.method-grid article{padding:20px;border-top:2px solid var(--line)}.method-grid .muted{font-size:12px}details{margin:16px 0}summary{padding:13px 0;border-bottom:1px solid var(--line);color:var(--green);cursor:pointer;font-size:14px}details p,li{font-size:14px}.evidence{padding-left:20px}.evidence li{border-bottom:1px solid var(--line);padding:12px 0}.evidence a{display:block;font-size:12px}.conditions{margin:25px 0;padding:24px;border:1px solid var(--line)}.condition-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px}.condition-fields label{font-size:13px;display:grid;gap:8px}.condition-fields select{padding:10px;background:var(--paper);border:1px solid var(--line);width:100%}.condition-result{margin-top:18px;padding:16px;background:var(--pale);font-size:14px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px;text-align:left}th,td{padding:13px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{min-width:100px;color:var(--green)}#panel{scroll-margin-top:25px}footer{border-top:1px solid var(--line);font-size:12px;color:var(--muted)}[hidden]{display:none!important}:focus-visible{outline:3px solid var(--gold);outline-offset:4px}@media(max-width:760px){header,main,footer{padding:18px 20px}h1{font-size:29px}h2{font-size:24px}.hero>p{font-size:15px}.project-brief,.proposal-grid,.method-grid,.condition-fields{grid-template-columns:1fr;gap:15px}.project-brief{margin:22px 0}.takeaway{font-size:16px}.graph-head{display:block}.path-tabs{gap:8px}.path-tabs button{padding:8px 10px;font-size:12px}dl>div{grid-template-columns:85px 1fr;gap:15px}dd{font-size:13px}.conditions{padding:18px}.proposal-grid article{padding:20px}th,td{padding:10px 8px;font-size:12px}.graph-wrap svg{min-width:850px}}@media print{header,.graph-wrap,.path-tabs,.conditions{display:none}.project-brief,.proposal-grid,.method-grid{display:block}body{background:white}main{padding:0}details{break-inside:avoid}h1{font-size:26pt}.evidence{font-size:10pt}}
</style></head><body><header><b>好设计 · 项目图谱</b><a href="档案.html?v=5.1.0">返回项目档案 ↗</a></header><main><section class="hero"><div class="eyebrow">从项目档案，到可检验的创新建议</div><h1>嫦娥经验，怎样帮助设计割胶机器人？</h1><p>先看问题、机制和条件怎样相连，再决定借鉴什么。以下是人工组织的迁移试读，关联判断与方案仍待验证。</p><div class="project-brief"><div><span>来源项目 / 冻结内容0.4.0</span><h3>嫦娥月球钻取采样系统</h3><p>2025年第十届好设计奖金奖。以接触反馈、设计取舍和分层验证为本次研究入口。</p><a href="档案.html?v=5.1.0">查看概况、八个数据维度与补充情况 ↗</a></div><div><span>假设的新任务</span><h3>割胶机器人</h3><p>希望稳定完成有效切割，同时约束耗皮、损伤与作业成本。设备形态、树况、预算和验收阈值尚未确定。</p></div></div><div class="takeaway">行业距离较大；控制思路与验证方法值得借鉴。具体机构、载荷和控制参数不能直接搬用。</div></section><section><div class="graph-head"><h2>看清楚关联发生在哪里</h2><p>实线：项目内容关系　虚线：迁移假设　红虚线：本次排除</p></div><p class="muted">点击任一经验或目标问题，下面会展开理由、方法、依据与验证。手机可横向滑动全图。</p><div class="graph-wrap">@@SVG@@</div><div class="path-tabs" role="group" aria-label="选择迁移路径">@@TABS@@</div><div id="panel" aria-live="polite"></div><section class="conditions" id="conditions"><h3>试着改变接触反馈这条路径的条件</h3><p class="muted">这不是现场控制器，只检查当前假设是否有继续研究的条件。</p><div class="condition-fields"><label for="feedback">是否允许接触反馈与动作调整？<select id="feedback"><option value="unknown">尚不清楚</option><option value="yes">允许，并具备改造条件</option><option value="no">不允许或无法改造</option></select></label><label for="depth">是否有经校准的切除量/深度测量依据？<select id="depth"><option value="unknown">尚不清楚</option><option value="yes">已有，并需核对适用范围</option><option value="no">暂时没有</option></select></label></div><div class="condition-result" id="condition-result" role="status"></div></section></section><details><summary>整体关联判断与阅读顺序</summary><div class="table-wrap"><table><thead><tr><th>维度</th><th>定性判断</th><th>理由</th></tr></thead><tbody>@@RELATION@@</tbody></table></div><p class="muted">不合成未经校准的百分比分数。引擎先读任务与未知条件，再读候选机制、反例/边界和证据，最后读方法及验证计划。</p></details><details><summary>相关割胶研究与本演示的边界</summary><p>视觉、测距和力控在割胶研究中已有探索。本演示不声称发明了这些技术，也没有证明迁移方案有效。</p><ul>@@SOURCES@@</ul></details><details><summary>结构化图谱与调用样例</summary><p class="muted">节点区分项目、需求、机制、陈述、来源、方法、建议和验证；边区分资料关系、平台解释、类比假设与排除。目标资料不写回嫦娥历史事实。</p><p><a href="项目图谱.json">图谱数据 JSON</a> · <a href="图谱调用样例.json">固定版本的调用样例 JSON</a></p></details></main><footer>迁移试读0.1.0 · 来源档案0.4.0 · 2026-10-20<br>人工组织的图谱演示；无在线AI/MCP调用，目标方案未验证，嫦娥档案质量自评保持55/100。</footer><script>
const demo=@@DATA@@;const panel=document.getElementById('panel');function choose(id,hash=true){if(!demo.panels[id])id='P01';panel.innerHTML=demo.panels[id];document.querySelectorAll('[data-select-path]').forEach(el=>{const selected=el.dataset.selectPath===id;el.classList.toggle('selected',selected);el.classList.toggle('faded',el.tagName.toLowerCase()==='g'&&!selected);if(el.tagName==='BUTTON')el.setAttribute('aria-pressed',String(selected))});document.querySelectorAll('[data-edge-path]').forEach(el=>el.classList.toggle('faded',el.dataset.edgePath!==id));document.getElementById('conditions').hidden=id!=='P01';if(hash)history.replaceState(null,'','#'+id)}document.querySelectorAll('[data-select-path]').forEach(el=>{el.addEventListener('click',()=>choose(el.dataset.selectPath));if(el.tagName.toLowerCase()==='g')el.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();choose(el.dataset.selectPath)}})});function checkConditions(){const f=document.getElementById('feedback').value,d=document.getElementById('depth').value;let text;if(f==='no')text='当前条件不支持这条接触反馈路径。可另研被动限位或仿形方案，仍需独立验证。';else if(f==='unknown')text='先确认是否允许接触反馈与动作调整，再判断这条路径。';else if(d==='unknown')text='还需明确切除量如何测量、余皮厚度如何校准；不能只用力值替代。';else if(d==='no')text='可以研究接触适应，但暂不能据此承诺割深或伤树控制。';else text='可进入末端台架对照研究；仍需农艺判据、材料校准和目标工况验证，不是可投用结论。';document.getElementById('condition-result').textContent=text}['feedback','depth'].forEach(id=>document.getElementById(id).addEventListener('change',checkConditions));window.addEventListener('hashchange',()=>choose(location.hash.slice(1),false));choose(location.hash.slice(1),false);checkConditions();
</script></body></html>'''
